package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    /** The grades the rate form takes. */
    private static final Pattern GRADE = Pattern.compile("[ABC]");

    /** A percent as the rate form takes it: 0.00 or more with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");

    /** A date as the rate form takes it. */
    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");

    private final RateRepository rates;
    private final RateVersionRepository versions;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateVersionRepository versions, SheetService sheets,
            ClaimRepository claims, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.claims = claims;
        this.versions = versions;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** Set a grade's rate from a date (null: from the beginning of time) through a date (null: for
     *  good) on the sheet: a grade and from-date that already have a rate keep the value it replaces as
     *  an older version and take the new one as their newest, the one in force (the sheet is created first if it was never loaded).
     *  One with a from-date on or after the sheet's today is forward-only: it applies only to claims
     *  added after it is saved, those already on any sheet keeping the rates that applied to them. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = pct.setScale(2);
        Long afterClaim = from != null && !from.isBefore(today) ? claims.findLastId() : null;
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
        try {
            if (rate == null) {
                rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, scaled, 1, afterClaim, List.of()));
            } else {
                versions.save(new RateVersion(rate.getId(), rate.getVersion(), rate.getPct(), rate.getTo()));
                rate.newVersion(scaled, to, afterClaim);
                rates.flush();
            }
        } catch (DataIntegrityViolationException e) {
            // set by another user at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Rate changed at the same moment");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + grade + " rate=" + scaled.toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        rollup.recordChanges(sheetId, user, before);
        return rate;
    }

    /** One pasted line as the rate form would submit it. */
    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    /** Set a rate for each line of grade,rate,from,to, in order, each exactly as the form sets it:
     *  the from- and to-dates may be absent or blank; blank lines are skipped. Every line is
     *  checked first by the rate form's rules (400 when any is not a rate the form takes, or there
     *  is none); one change, so when any line is refused nothing is set. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n|\\r")) {
            n++;
            if (raw.isBlank()) continue;
            String[] f = raw.split(",", -1);
            if (f.length < 2 || f.length > 4) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": give grade,rate,from,to");
            }
            String grade = f[0].trim();
            String pct = f[1].trim();
            String from = f.length > 2 ? f[2].trim() : "";
            String to = f.length > 3 ? f[3].trim() : "";
            if (!GRADE.matcher(grade).matches() || !PCT.matcher(pct).matches()) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": not a rate the form takes");
            }
            LocalDate fromDate = date(from, n);
            LocalDate toDate = date(to, n);
            if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": to-date before from-date");
            }
            lines.add(new Line(grade, new BigDecimal(pct), fromDate, toDate));
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) {
            set.add(set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        }
        return set;
    }

    /** A pasted date: null when blank; 400 when it is not a date as yyyy-mm-dd. */
    private static LocalDate date(String value, int line) {
        if (value.isEmpty()) return null;
        try {
            if (DATE.matcher(value).matches()) return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            // falls through to the refusal
        }
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + line + ": not a date as yyyy-mm-dd");
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** A grade's rate as the screen shows it: the percent always with two decimals, and its
     *  from-date (null when it applies from the beginning of time), to-date (null: for good) and how
     *  many versions it has (the one shown, its newest, being in force); for a forward-only newest
     *  version the highest claim id there was when it was saved (only claims added after it apply
     *  it), and the earlier versions claims added before it apply instead, newest first. */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct, int version, Long afterClaim,
            List<EarlierView> earlier) {
        static RateView of(Rate r) {
            return new RateView(r.getGrade(), r.getFrom(), r.getTo(), r.getPct().setScale(2).toPlainString(), r.getVersion(),
                    r.getAfterClaim(), r.getEarlier().stream().map(EarlierView::of).toList());
        }
    }

    /** An earlier version of a rate as a claim added before its later forward-only one applies it. */
    public record EarlierView(String pct, LocalDate to, Long afterClaim) {
        static EarlierView of(Rate.Earlier e) {
            return new EarlierView(e.pct().setScale(2).toPlainString(), e.to(), e.afterClaim());
        }
    }

    /** A rate as the form submits it: a percent of 0.00 or more with up to two decimals, and an
     *  optional from-date (absent: from the beginning of time) and to-date (absent: for good), not
     *  before the from-date. */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,7}(\\.\\d{1,2})?") String pct, LocalDate from, LocalDate to) {
        @AssertTrue(message = "to-date before from-date")
        public boolean isToNotBeforeFrom() {
            return from == null || to == null || !to.isBefore(from);
        }
    }

    /** The rate import box's text: lines of grade,rate,from,to. */
    public record ImportForm(@NotNull @Size(max = 1_000_000) String text) {
    }

    private final RateService service;
    private final HistoryService history;
    private final RateChain chain;

    public RateController(RateService service, HistoryService history, RateChain chain) {
        this.service = service;
        this.chain = chain;
        this.history = history;
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<Rate> rates = asOf == null ? service.list(sheetId) : history.asOf(sheetId, asOf).rates();
        return rates.stream().map(RateView::of).toList();
    }

    /** The rates of each of the sheet's ancestors, its parent's first (shown as of a date, each
     *  as it stood at the end of that date): a grade with no rate of its own in force on a date
     *  takes the first of them that has one. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<List<Rate>> inherited = asOf == null ? chain.inherited(sheetId)
                : chain.ancestors(sheetId).stream().map(a -> history.asOf(a, asOf).rates()).toList();
        return inherited.stream().map(l -> l.stream().map(RateView::of).toList()).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm body) {
        return RateView.of(service.set(sheetId, user.trim(), grade, body.from(), body.to(), new BigDecimal(body.pct())));
    }

    /** The rates set by an import, in the order of their lines. */
    @PostMapping("/import")
    public List<RateView> importRates(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ImportForm body) {
        return service.importRates(sheetId, user.trim(), body.text()).stream().map(RateView::of).toList();
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/** The rates in force on a sheet: a grade with no rate of its own in force on a date takes its
 *  parent sheet's for that grade and date, then its parent's parent's, up to {@link #LEVELS} levels up. */
@Component
public class RateChain {

    /** How many levels of parent sheets a rate is looked for in. */
    public static final int LEVELS = 3;

    private final RateRepository rates;
    private final SheetRepository sheets;

    public RateChain(RateRepository rates, SheetRepository sheets) {
        this.rates = rates;
        this.sheets = sheets;
    }

    /** The ids of the sheet's ancestors, its parent first, up to {@link #LEVELS} levels up. */
    @Transactional(readOnly = true)
    public List<String> ancestors(String sheetId) {
        List<String> out = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(sheetId));
        String at = sheetId;
        while (out.size() < LEVELS) {
            String parent = sheets.findById(at).map(Sheet::getParent).orElse(null);
            if (parent == null || !seen.add(parent)) {
                break;
            }
            out.add(parent);
            at = parent;
        }
        return out;
    }

    /** The rates of each of the sheet's ancestors, its parent's first. */
    @Transactional(readOnly = true)
    public List<List<Rate>> inherited(String sheetId) {
        return ancestors(sheetId).stream().map(rates::findBySheetIdOrderByGradeAsc).toList();
    }

    /** The rates in force on the sheet, with what it inherits, as one list. */
    @Transactional(readOnly = true)
    public List<Rate> effective(String sheetId) {
        return effective(sheetId, rates.findBySheetIdOrderByGradeAsc(sheetId));
    }

    /** The rates in force on the sheet given its own (as they stood on a date, say), with what it
     *  inherits from its ancestors now, as one list. */
    @Transactional(readOnly = true)
    public List<Rate> effective(String sheetId, List<Rate> own) {
        return flatten(sheetId, own, inherited(sheetId));
    }

    /** The sheet's own rates and those it inherits, to apply to its claims. */
    @Transactional(readOnly = true)
    public Levels levels(String sheetId) {
        return new Levels(sheetId, rates.findBySheetIdOrderByGradeAsc(sheetId), inherited(sheetId));
    }

    /** A sheet's own rates and those of each of its ancestors (its parent's first): {@link #inForce}
     *  the rates in force on it as one list, as the rates panel shows them, and {@link #forClaim} the
     *  ones a claim applies, leaving out the forward-only versions saved after it was added. */
    public static final class Levels {

        private final String sheetId;
        private final List<Rate> own;
        private final List<List<Rate>> inherited;
        private final List<Rate> inForce;
        /** Every forward-only mark the rates have, lowest first. */
        private final List<Long> marks;
        /** The rates claims apply, by how many of the marks they were added after. */
        private final Map<Integer, List<Rate>> byMark = new HashMap<>();

        public Levels(String sheetId, List<Rate> own, List<List<Rate>> inherited) {
            this.sheetId = sheetId;
            this.own = own;
            this.inherited = inherited;
            this.inForce = flatten(sheetId, own, inherited);
            TreeSet<Long> all = new TreeSet<>();
            List<List<Rate>> levels = new ArrayList<>(inherited);
            levels.add(own);
            levels.forEach(l -> l.forEach(r -> {
                if (r.getAfterClaim() != null) {
                    all.add(r.getAfterClaim());
                }
                r.getEarlier().forEach(e -> {
                    if (e.afterClaim() != null) {
                        all.add(e.afterClaim());
                    }
                });
            }));
            this.marks = List.copyOf(all);
        }

        /** The rates in force on the sheet, with what it inherits, as one list. */
        public List<Rate> inForce() {
            return inForce;
        }

        /** The rates, with what the sheet inherits, as one list, as a claim added as {@code added}
         *  (null: one added now) applies them. */
        public List<Rate> forClaim(Long added) {
            if (marks.isEmpty() || added == null) {
                return inForce;
            }
            // how many marks it was added after (one added as a mark itself was there when it was saved)
            int at = Collections.binarySearch(marks, added);
            int passed = at >= 0 ? at : -at - 1;
            if (passed == marks.size()) {
                return inForce;
            }
            return byMark.computeIfAbsent(passed, k -> flatten(sheetId, Rate.forClaim(own, added),
                    inherited.stream().map(l -> Rate.forClaim(l, added)).toList()));
        }
    }

    /** The grade's rate on a date on the sheet, as a claim added as {@code added} (null: one added
     *  now) applies it: its own, else the nearest ancestor's. */
    @Transactional(readOnly = true)
    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate on, Long added) {
        Optional<Rate> own = inForce(Rate.forClaim(rates.findBySheetIdAndGrade(sheetId, grade), added), grade, on);
        if (own.isPresent()) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            Optional<Rate> found = inForce(Rate.forClaim(rates.findBySheetIdAndGrade(ancestor, grade), added), grade, on);
            if (found.isPresent()) {
                return found;
            }
        }
        return Optional.empty();
    }

    /** The grade's rate in force on a date on the sheet: its own, else the nearest ancestor's. */
    @Transactional(readOnly = true)
    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate on) {
        Optional<Rate> own = rates.findInForce(sheetId, grade, on);
        if (own.isPresent()) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            Optional<Rate> found = rates.findInForce(ancestor, grade, on);
            if (found.isPresent()) {
                return found;
            }
        }
        return Optional.empty();
    }

    /** One list of rates that has, for each grade and date, the rate in force then on the first of
     *  the levels (the sheet's own, then each ancestor's) that has one: the dates are cut where any
     *  level's rate starts or ends, and each piece takes the rate the levels give it. With nothing
     *  inherited it is the sheet's own. */
    public static List<Rate> flatten(String sheetId, List<Rate> own, List<List<Rate>> inherited) {
        if (inherited.stream().allMatch(List::isEmpty)) {
            return own;
        }
        List<List<Rate>> levels = new ArrayList<>();
        levels.add(own);
        levels.addAll(inherited);
        TreeSet<String> grades = new TreeSet<>();
        levels.forEach(l -> l.forEach(r -> grades.add(r.getGrade())));
        List<Rate> out = new ArrayList<>();
        for (String grade : grades) {
            TreeSet<LocalDate> cuts = new TreeSet<>();
            for (List<Rate> level : levels) {
                for (Rate r : level) {
                    if (r.getGrade().equals(grade)) {
                        if (r.getFrom() != null) {
                            cuts.add(r.getFrom());
                        }
                        if (r.getTo() != null) {
                            cuts.add(r.getTo().plusDays(1));
                        }
                    }
                }
            }
            List<LocalDate> starts = new ArrayList<>();
            starts.add(null);
            starts.addAll(cuts);
            for (int i = 0; i < starts.size(); i++) {
                LocalDate start = starts.get(i);
                LocalDate next = i + 1 < starts.size() ? starts.get(i + 1) : null;
                LocalDate end = next == null ? null : next.minusDays(1);
                LocalDate on = start != null ? start : end != null ? end : LocalDate.EPOCH;
                for (List<Rate> level : levels) {
                    Optional<Rate> found = inForce(level, grade, on);
                    if (found.isPresent()) {
                        out.add(new Rate(sheetId, grade, start, end, found.get().getPct()));
                        break;
                    }
                }
            }
        }
        return out;
    }

    private static Optional<Rate> inForce(List<Rate> level, String grade, LocalDate on) {
        return level.stream()
                .filter(r -> r.getGrade().equals(grade) && r.appliesOn(on))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.runsThrough(on));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Embeddable;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.history.HistoryListener;

/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
 *  (from the beginning of time when it has none) through its to-date (for good when it has none).
 *  A version saved forward-only (its from-date on or after the sheet's today then) applies only to
 *  claims added after it was saved; a claim added before falls back to the earlier versions. */
@Entity
@EntityListeners(HistoryListener.class)
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 9, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    @Column(name = "version", nullable = false)
    private int version = 1;

    /** For a forward-only newest version, the highest claim id there was when it was saved: only
     *  claims added after that apply it. Null: it applies to every claim. */
    @Column(name = "after_claim")
    private Long afterClaim;

    /** The versions a claim added before the newest (forward-only) one applies instead, newest
     *  first, up to and including the first that applies to every claim; empty when the newest
     *  applies to every claim. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "rate_earlier", joinColumns = @JoinColumn(name = "rate_id"))
    @OrderColumn(name = "position")
    private List<Earlier> earlier = new ArrayList<>();

    /** An earlier version of a rate as a claim added before a later forward-only one applies it:
     *  its percent and to-date, and (when it was itself forward-only) the highest claim id there was
     *  when it was saved. */
    @Embeddable
    public record Earlier(
            @Column(name = "pct", nullable = false, precision = 9, scale = 2) BigDecimal pct,
            @Column(name = "to_date") LocalDate to,
            @Column(name = "after_claim") Long afterClaim) {

        /** Whether the version applies to a claim added as {@code added} (null: one added now). */
        public boolean appliesTo(Long added) {
            return afterClaim == null || added == null || added > afterClaim;
        }
    }

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        this.pct = pct;
    }

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct, int version) {
        this(sheetId, grade, from, to, pct);
        this.version = version;
    }

    /** A rate with its forward-only mark and earlier versions, as a copy or a version rebuilt from
     *  history carries them. */
    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct, int version,
            Long afterClaim, List<Earlier> earlier) {
        this(sheetId, grade, from, to, pct, version);
        this.afterClaim = afterClaim;
        this.earlier = new ArrayList<>(earlier);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    /** The first date the rate is in force; null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** Whether the rate is in force on a date (it may be overtaken by a later one). */
    public boolean appliesOn(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    /** The last date the rate applies; null when it applies for good. */
    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    /** Whether the rate still applies on a date it is in force (not past its to-date). */
    public boolean runsThrough(LocalDate date) {
        return to == null || !to.isBefore(date);
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }

    /** How many versions the rate has: this, the newest, is the one in force. */
    public int getVersion() {
        return version;
    }

    /** For a forward-only newest version, the highest claim id there was when it was saved; null
     *  when it applies to every claim. */
    public Long getAfterClaim() {
        return afterClaim;
    }

    /** The versions a claim added before the newest one applies instead, newest first. */
    public List<Earlier> getEarlier() {
        return List.copyOf(earlier);
    }

    /** Replace the rate's percent and to-date with a new version, its version count going up by
     *  one: forward-only when {@code afterClaim} (the highest claim id there is now) is given, the
     *  version it replaces then kept for the claims added before it. */
    public void newVersion(BigDecimal pct, LocalDate to, Long afterClaim) {
        if (afterClaim == null) {
            earlier.clear();
        } else {
            if (this.afterClaim == null) {
                earlier.clear();
            }
            earlier.add(0, new Earlier(this.pct, this.to, this.afterClaim));
        }
        this.pct = pct;
        this.to = to;
        this.afterClaim = afterClaim;
        this.version++;
    }

    /** The rate as it applies to a claim added as {@code added} (null: one added now): the newest
     *  version, else the newest earlier one that applies to it; none when no version does. */
    public Optional<Rate> forClaim(Long added) {
        if (afterClaim == null || added == null || added > afterClaim) {
            return Optional.of(this);
        }
        return earlier.stream()
                .filter(e -> e.appliesTo(added))
                .findFirst()
                .map(e -> new Rate(sheetId, grade, from, e.to(), e.pct(), version));
    }

    /** Of rates, each as it applies to a claim added as {@code added}, leaving out those that do not. */
    public static List<Rate> forClaim(List<Rate> rates, Long added) {
        if (rates.stream().allMatch(r -> r.afterClaim == null)) {
            return rates;
        }
        return rates.stream().flatMap(r -> r.forClaim(added).stream()).toList();
    }
}

