@Injectable({ providedIn: 'root' })
export class CrewsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's crews, in the order they were added. */
  list(sheetId: string): Promise<Crew[]> {
    return firstValueFrom(this.http.get<Crew[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** Add a crew led by a person; resolves to the sheet's crews with it. */
  add(sheetId: string, name: string, leadId: number): Promise<Crew[]> {
    return firstValueFrom(this.http.post<Crew[]>(this.url(sheetId), { name, leadId }, { headers: this.headers() }));
  }

  /** Add a person to a crew; resolves to the sheet's crews with them. */
  addMember(sheetId: string, crew: string, personId: number): Promise<Crew[]> {
    return firstValueFrom(
      this.http.post<Crew[]>(`${this.url(sheetId)}/members`, { crew, personId }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/crews`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function crewError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name for the crew and choose its lead.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The sheet has a crew or a pool of that name already.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}

export function crewMemberError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That person leads the crew or is in it already.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That crew or person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}
package net.officefloor.hq.app.crew;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class CrewService {

    /** A crew with its members, in the order they were added. */
    public record CrewWithMembers(Crew crew, List<CrewMember> members) {
    }

    private final CrewRepository crews;
    private final CrewMemberRepository members;
    private final PersonRepository people;
    private final PoolRepository pools;
    private final SheetService sheets;
    private final Audit audit;

    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
            PoolRepository pools, SheetService sheets, Audit audit) {
        this.crews = crews;
        this.members = members;
        this.people = people;
        this.pools = pools;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's crews in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<CrewWithMembers> list(String sheetId) {
        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<CrewMember>> byCrew = members.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList())
                .stream().collect(Collectors.groupingBy(CrewMember::getCrewId));
        return all.stream().map(c -> new CrewWithMembers(c, byCrew.getOrDefault(c.getId(), List.of()))).toList();
    }

    /** Add a crew led by a person of the sheet; refused (404) for a person not on the sheet, (409)
     *  when the sheet has a crew or a pool (a crew is a pool too) of the name already. */
    @Transactional
    public Crew add(String sheetId, String user, String name, long leadId) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        Person lead = people.findByIdAndSheetId(leadId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (crews.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a crew of that name");
        }
        if (pools.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a pool of that name");
        }
        Crew crew = crews.saveAndFlush(new Crew(sheetId, name, lead.getId()));
        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + name
                + " lead=" + lead.getName());
        return crew;
    }

    /** Add a person of the sheet to a crew; refused (404) for a crew or person not on the sheet,
     *  (409) when the person is the crew's lead or in the crew already. */
    @Transactional
    public CrewMember addMember(String sheetId, String user, String crewName, long personId) {
        sheets.lock(sheetId);
        Crew crew = crews.findBySheetIdAndNameIgnoreCase(sheetId, crewName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew"));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (crew.getLeadId().equals(person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person leads the crew");
        }
        if (members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person is in the crew already");
        }
